import currency
__game = Hash(default_value=0, contract='con_survival1', name='game')
__operator = Variable(contract='con_survival1', name='operator')
__distributionAmount = Variable(contract='con_survival1', name=
    'distributionAmount')
__zombiesAmount = Variable(contract='con_survival1', name='zombiesAmount')
__survivorAmount = Variable(contract='con_survival1', name='survivorAmount')


def ____(vk: str):
    __operator.set(vk)
    __distributionAmount.set(0)
    __zombiesAmount.set(0)
    __survivorAmount.set(0)
    __game['last_redeem'] = now
    __game['play_cost'] = 20
    __game['redeem_time'] = 1
    __game['fail_attack'] = 5


@__export('con_survival1')
def attack_survivor():
    caller = ctx.caller
    GAMEID = __game['gameId']
    SURVIVOR = __game[GAMEID, 'survivor']
    ATTACK_SHIELD = __shield()
    __game[GAMEID, 'game_amount'] += 20
    random.seed()
    randomFirstAttack = random.randint(1, 33)
    if randomFirstAttack == 33:
        if ATTACK_SHIELD is True:
            __game[GAMEID, SURVIVOR, 'have_shield'] = 0
        else:
            STEAL_AMOUNT = 50 * (now - __game[GAMEID, 'last_redeem']).hours
            __game['gameId'] = hashlib.sha3(str(now))
            GAMEID = __game['gameId']
            __game[GAMEID, 'survivor'] = caller
            __game[GAMEID, 'game_amount'] = 0
            __game[GAMEID, 'last_redeem'] = now
            if STEAL_AMOUNT > 0:
                currency.transfer_from(STEAL_AMOUNT, caller, __operator.get())
            return {'survivor': caller, 'time': now, 'status':
                'new_survivor', 'attack': True, 'fatal_attack': True,
                'amount': STEAL_AMOUNT, 'gameId': GAMEID}
    else:
        randomSecondAttack = random.randint(1, 10)
        if randomFirstAttack == 10:
            if __game[GAMEID, SURVIVOR, 'survivor_life'] < 2:
                STEAL_AMOUNT = 50 * (now - __game[GAMEID, 'last_redeem']).hours
                __game['gameId'] = hashlib.sha3(str(now))
                GAMEID = __game['gameId']
                __game[GAMEID, 'survivor'] = caller
                __game[GAMEID, 'game_amount'] = 0
                __game[GAMEID, 'last_redeem'] = now
                if STEAL_AMOUNT > 0:
                    currency.transfer_from(STEAL_AMOUNT, caller, __operator
                        .get())
                return {'survivor': caller, 'time': now, 'status':
                    'new_survivor_second_attack', 'attack': True,
                    'fatal_attack': True, 'amount': STEAL_AMOUNT, 'gameId':
                    GAMEID}
            else:
                __game[GAMEID, SURVIVOR, 'survivor_life'] -= 1
                STEAL_AMOUNT = 50 * (now - __game[GAMEID, 'last_redeem']
                    ).hours * decimal('0.15')
                __game[GAMEID, 'game_amount'] -= STEAL_AMOUNT
                if STEAL_AMOUNT > 0:
                    currency.transfer_from(STEAL_AMOUNT, caller, __operator
                        .get())
                return {'survivor': SURVIVOR, 'time': now, 'status':
                    'steal_life', 'attack': True, 'fatal_attack': False,
                    'amount': STEAL_AMOUNT, 'gameId': GAMEID}
        else:
            currency.transfer_from(__game['fail_attack'], SURVIVOR,
                __operator.get())
            fail_amount = __game['fail_attack']
            __game[GAMEID, 'game_amount'] -= fail_amount
            return {'survivor': SURVIVOR, 'time': now, 'status':
                'fail_attack', 'attack': False, 'fatal_attack': False,
                'amount': fail_amount, 'gameId': GAMEID}


@__export('con_survival1')
def redeem():
    caller = ctx.caller
    assert (now - __game[GAMEID, 'last_redeem']).hours > 1, 'Not Cant redeem'
    SURVIVOR = __game['survivor']
    GAMEID = __game['gameId']
    if caller == SURVIVOR:
        AMOUNT = 50 * (now - __game[GAMEID, 'last_redeem']).hours
        if AMOUNT > 0:
            __game[GAMEID, 'last_redeem'] = now
            __game[GAMEID, 'game_amount'] -= AMOUNT
            currency.transfer_from(AMOUNT, SURVIVOR, __operator.get())
            return AMOUNT


@__export('con_survival1')
def start(account: str):
    __game['gameId'] = hashlib.sha3(str(now))
    GAMEID = __game['gameId']
    __game[GAMEID, 'survivor'] = account
    __game[GAMEID, 'last_redeem'] = now
    __game[GAMEID, 'game_amount'] = 1000
    __game[GAMEID, account, 'survivor_life'] = 5


def __shield():
    GAMEID = __game['gameId']
    SURVIVOR = __game[GAMEID, 'survivor']
    HAVE_SHIELD = __game[GAMEID, SURVIVOR, 'have_shield']
    if HAVE_SHIELD == 1:
        random.seed()
        randomShield = random.randint(1, 2)
        if randomShield == 1:
            return True
    else:
        return False


@__export('con_survival1')
def set_nick_name(nickname: str):
    caller = ctx.caller
    assert len(nickname) <= 25, 'Nickname too long (25 chars max).'
    assert len(nickname) > 0, 'Nickname too short.'
    names_uid = hashlib.sha3(nickname.lower().replace(' ', ''))
    assert not __game['nicknames', names_uid
        ], 'A form of this name already belongs to ' + balances['nicknames',
        names_uid]
    __game[caller, 'nickname'] = nickname
    __game['nicknames', names_uid] = nickname
